INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/394547','{"collected_at":"2026-10-31T00:01:03.640015+00:00","company":"렛유인에듀","deadline":"2026-11-30","description":"반도체 현장 경험과 전공 지식을 바탕으로, 실무 교육 콘텐츠와 커리큘럼을 함께 기획하고 설계합니다. • 반도체 교육과정 기획 - 무엇을 어떤 흐름으로 가르칠지 구조 설계 • 실감형(가상훈련) 콘텐츠를 교육 흐름에 맞게 연계한 실습형 교육 설계 • 학습자의 수준·니즈를 반영한 맞춤형 교육 과정 구성 • 교수자용 가이드, 교안, 학습 자료 등 교육 실행 자료 기획 • 교육 제안서·사업계획서 등 문서화 (양식·가이드 제공) • 교수자·학습자 피드백을 반영한 교육 개선 교육, 교재·교육기획","employment_type":"regular","experience":"경력 1~10년 / 정규직","keyword":"교육","link":"https://www.wanted.co.kr/wd/394547","location":"한국 서울 강남구 서울 강남구 테헤란로8길 41, 2층","matched_keywords":["교육"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=%EA%B5%90%EC%9C%A1&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"에듀테크 반도체 교육 콘텐츠 기획자 (엔지니어 우대) [경력 1~10년 / 정규직]"}','611b69b19a62eff63749f5e72ca9f1aadadf03c2cf0516d5211dee34617533ee','2026-10-27T00:01:28+00:00','2026-10-31T00:01:27+00:00','2026-10-27T00:01:28+00:00');
